    private void openSection(String section) {
        adminmain main = findMain();
        if (main != null) {
            main.showSection(section);
        }
    }

    private adminmain findMain() {
        java.awt.Window window = SwingUtilities.getWindowAncestor(this);
        return window instanceof adminmain main ? main : null;
    }

    private void loadSummary() {
        LocalDate today = LocalDate.now();
        String period = today.getMonth().getDisplayName(TextStyle.FULL, Locale.ENGLISH)
                + " 1–" + today.lengthOfMonth() + ", " + today.getYear();
        lblSubtitle.setText("Payroll period: " + period);
        lblPeriodValue.setText(period);
        lblPayDateValue.setText(today.withDayOfMonth(Math.min(30, today.lengthOfMonth())).toString());
    }

